{"command":"python3 -c "
import csv

# Read the input file
with open('outputs/t11_city_indicator_matrix.csv', 'r', newline='') as f:
    reader = csv.reader(f)
    header = next(reader)
    indicator_cols = header[3:]

missing_counts = {}
total_rows = 0

for row in reader:
    total_rows += 1
    for i, col in enumerate(indicator_cols):
        if i < len(row) and row[i] == '':
            missing_counts[col] = missing_counts.get(col, 0) + 1

print('Total rows:', total_rows)
for col in sorted(missing_counts.keys()):
    rate = missing_counts[col] / total_rows
    print(f'{col}: {missing_counts[col]} missing ({rate:.6f})')
""}
